    protected string GetAppVersion()
    {
        // 优先从 changelog.xml 读取最新版本号
        try
        {
            string xmlPath = Server.MapPath("~/changelog.xml");
            if (System.IO.File.Exists(xmlPath))
            {
                System.Xml.XmlDocument doc = new System.Xml.XmlDocument();
                doc.Load(xmlPath);
                System.Xml.XmlNode node = doc.SelectSingleNode("//changelog/version[1]");
                if (node != null && node.Attributes["ver"] != null)
                    return node.Attributes["ver"].Value;
            }
        }
        catch { }
        // 回退：从 DLL 读取版本号
        try
        {
            string dllPath = Server.MapPath("~/bin/LearnSite.dll");
            if (System.IO.File.Exists(dllPath))
            {
                System.Diagnostics.FileVersionInfo fvi = System.Diagnostics.FileVersionInfo.GetVersionInfo(dllPath);
                return "v" + fvi.FileVersion;
            }
        }
        catch { }
        return "";
    }

