    private object TDecodeCookie(string typeName, string cookieValue)
    {
        Type cookType = typeof(LearnSite.Common.CookieHelp).Assembly.GetType(typeName);
        if (cookType == null) return null;
        object model = Activator.CreateInstance(cookType);
        System.Reflection.MethodInfo toModel = cookType.GetMethod("ToModel", tFlags);
        if (toModel != null) toModel.Invoke(model, new object[] { cookieValue });
        return model;
    }

    private string TGetProp(object model, string propName)
    {
        if (model == null) return "";
        System.Reflection.PropertyInfo prop = model.GetType().GetProperty(propName);
        if (prop == null) return "";
        object val = prop.GetValue(model, null);
        return val != null ? val.ToString() : "";
    }

    private void LoadTeacherUserInfo()
    {
        int hid = 0;
        try
        {
            HttpCookie tc = Request.Cookies[LearnSite.Common.CookieHelp.teaCookieNname];
            if (tc != null && !string.IsNullOrEmpty(tc.Value))
            {
                object t = TDecodeCookie("LearnSite.Model.TeaCook", tc.Value);
                string name = TGetProp(t, "Hname");
                if (!string.IsNullOrEmpty(name))
                {
                    // 尝试URL解码，如果包含%编码
                    try
                    {
                        if (name.Contains("%"))
                        {
                            name = Server.UrlDecode(name);
                        }
                    }
                    catch { }
                    tUserName = name;
                    tUserInitial = name.Substring(0, 1);
                }
                string sid = TGetProp(t, "Hid");
                if (!string.IsNullOrEmpty(sid)) int.TryParse(sid, out hid);
            }
        }
        catch { }
        if (hid > 0)
        {
            string[] exts = { ".png", ".jpg", ".jpeg", ".gif", ".webp" };
            foreach (string ext in exts)
            {
                string fp = Server.MapPath("~/images/avatars/" + hid + ext);
                if (System.IO.File.Exists(fp))
                {
                    tUserAvatarUrl = ResolveUrl("~/images/avatars/" + hid + ext) + "?t=" + System.IO.File.GetLastWriteTime(fp).Ticks;
                    break;
                }
            }
        }
    }

    protected void Page_Init(object sender, EventArgs e)
    {
        string icoPath = Server.MapPath("~/favicon.ico");
        if (System.IO.File.Exists(icoPath))
        {
            LitFavicon.Text = "<link rel=\"icon\" type=\"image/x-icon\" href=\"" + ResolveUrl("~/favicon.ico") + "?v=" + System.IO.File.GetLastWriteTime(icoPath).Ticks + "\" />";
        }
        else
        {
            string pngPath = Server.MapPath("~/favicon.png");
            if (System.IO.File.Exists(pngPath))
                LitFavicon.Text = "<link rel=\"icon\" type=\"image/png\" href=\"" + ResolveUrl("~/favicon.png") + "?v=" + System.IO.File.GetLastWriteTime(pngPath).Ticks + "\" />";
        }
        Page.Title = GetSiteTitle() + " - \u6559\u5E08\u5E73\u53F0";
        LoadTeacherUserInfo();

        // Auth guard: redirect to login if no valid teacher cookie (skip login page itself)
        string reqPath = Request.Url.AbsolutePath.ToLower();
        if (!reqPath.EndsWith("/index.aspx") && !reqPath.EndsWith("/teacher/"))
        {
            HttpCookie tc = Request.Cookies[LearnSite.Common.CookieHelp.teaCookieNname];
            if (tc == null || string.IsNullOrEmpty(tc.Value))
            {
                Response.Redirect(ResolveUrl("~/teacher/index.aspx"));
            }
        }
    }

